  const waitingFare=()=>Math.max(0,state.ride.waitingMinutes-state.rules.waitFree)*state.rules.waitPrice;
  const total=()=>Math.round(((state.ride.committed&&state.ride.price!=null?state.ride.price:baseFare())+state.booking.boost+waitingFare())*100)/100;
  const paymentLabel=()=>state.booking.payment==='transfer'?'Переводом водителю':'Наличными';
  const statusLabel=()=>({searching:'Ищем водителя',accepted:'Водитель едет к вам',driver_waiting:'Водитель приехал',in_progress:'Вы в пути',completed:'Поездка завершена',cancelled:'Поездка отменена',timeout:'Водитель не найден'})[state.ride.status];
  const person=(name,sub,avatar='')=>`<div class="flow-person"><span class="flow-avatar">${avatar?`<img src="${E(avatar)}" alt="Фото профиля">`:E(name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><div><strong>${E(name)}</strong><small>${E(sub)}</small></div></div>`;
