  register('raise-price','Водитель пока не найден','passenger',[],()=>lead(`Предлагаем повысить стоимость на ${money(state.rules.searchStep)}. В приложении предложение появляется через ${state.rules.searchMinutes} минуты поиска.`)+row('Сейчас',money(total()))+row('После повышения',money(total()+state.rules.searchStep))+actions(button('Повысить цену','raise-confirm','primary'),button('Оставить текущую','active','quiet')));
  register('rating','Оценка поездки','passenger',[],()=>lead(currentParams.driver?'Как прошла поездка с пассажиром?':'Как прошла поездка с водителем?')+`<div class="flow-stars" role="group" aria-label="Оценка">${[1,2,3,4,5].map(n=>`<button type="button" data-do="star" data-value="${n}" aria-label="${n} из 5" aria-pressed="${n<=state.selectedRating}">★</button>`).join('')}</div>`+actions(button('Отправить оценку','rate-submit','primary',state.selectedRating?'':'disabled'),button('Не сейчас','rate-skip','quiet')));
  register('history','Ваши поездки','passenger',['passenger/orders-screen.tsx'],()=>lead('Активные, завершённые и отменённые заказы.')+orderList(false)+(state.historyMore?'':actions(button('Показать более ранние поездки','history-more','quiet')))+demoControls(button('Пустая история','empty-history','quiet')));
