  register('application','Стать водителем','passenger',['passenger/driver-application-screen.tsx'],()=>state.application?.status==='pending'?badge('На проверке','warn')+note('Заявка сохранена в макете. Её можно одобрить или отклонить в диспетчерской.')+go('Открыть модерацию','applications'):(state.application?.status==='rejected'?note(state.application.reason||'Проверьте данные и отправьте новую заявку.','warn'):'')+form('application',field('name','ФИО',state.application?.name||state.profile.name,'text','required')+field('phone','Телефон',state.profile.phone,'tel','required')+field('license','Номер водительского удостоверения','','text','required')+vehicleFields(state.application||state.driver)+check('terms','Принимаю условия работы водителя',false,'Подтверждаю достоверность сведений и наличие документов',true)+check('data','Согласен на обработку данных заявки, прав и автомобиля',false,'Отдельное согласие кандидата в водители',true),'Отправить заявку')+go('Условия работы и согласия','legal'));
