  function profileForm(setup){return form(setup?'setup':'personal',field('name','Имя и фамилия',state.profile.name,'text','required minlength="2" maxlength="100"')+select('gender','Пол',state.profile.gender,[['male','Мужской'],['female','Женский']]),setup?'Сохранить и продолжить':'Сохранить изменения')}
  function addressResults(query){const values=[...new Set(['Граховская школа','Ачинцева, 5','Колпакова, 1Б','Азина, 12',...state.places.filter(p=>p.active).map(p=>p.name)])].filter(s=>s.toLocaleLowerCase('ru').includes(query.toLocaleLowerCase('ru')));return values.length?values.map(s=>`<button class="flow-link" type="button" data-do="pick-address" data-value="${E(s)}"><span>${E(s)}<small>Грахово · адрес из демонстрационного справочника</small></span><span>↗</span></button>`).join(''):'<p class="flow-empty">Точного совпадения нет. Введите адрес вручную ниже.</p>'}
  function vehicleFields(v){return `<div class="flow-grid">${field('make','Марка автомобиля',v.make,'text','required')}${field('model','Модель',v.model,'text','required')}${field('year','Год выпуска',v.year,'number','required min="1950" max="2027"')}${field('plate','Госномер',v.plate,'text','required')}</div><div class="flow-plate-preview" id="flow-plate-preview">${plate(v.plate)}</div>`+select('color','Цвет',v.color||'Белый',['Белый','Синий','Чёрный','Серебристый','Красный','Зелёный'].map(s=>[s,s]))+check('child','Есть детское кресло',v.child,'Детский тариф доступен после проверки')}
  function activeView(driver){const r=state.ride;let html=badge(statusLabel())+miniMap()+routeRows()+row('Оплата',paymentLabel())+row('Итого',money(total()));if(state.booking.comment)html+=note(state.booking.comment);
    if(r.queued)html+=note('Водитель завершает предыдущий заказ. После него поедет к вам.','warn');
    if(r.status==='searching')return html+lead('Свободные водители видят ваш заказ.')+actions(button('Повысить стоимость','raise-price'),button('Отменить','cancel','quiet'))+demoControls(button('Водитель найден','found','primary')+button('Не найден','search-timeout','quiet'));
    if(['cancelled','timeout'].includes(r.status))return html+note(r.reason||'Поиск завершён. Можно попробовать ещё раз.','warn')+actions(button('Новый заказ','new-booking','primary'));
    if(['completed'].includes(r.status))return html+actions(button(driver?'Оценить пассажира':'Оценить водителя','rate-open','primary',driver?'data-driver="true"':''),button(driver?'К новым заказам':'Новая поездка',driver?'driver-new':'new-booking'));
    html+=person(driver?state.profile.name:state.driver.name,driver?'Пассажир · ★ 4,9':`${state.driver.color} ${state.driver.make} ${state.driver.model}`)+(!driver?plateRow('Госномер',state.driver.plate):'')+actions(button('Позвонить','call'),button('Написать','chat'),...(driver?[button('Маршрут','navigator')]:[]));
    if(r.waiting||r.waitingMinutes)html+=note(`Ожидание ${r.waitingMinutes} мин · первые ${state.rules.waitFree} мин бесплатно, затем ${money(state.rules.waitPrice)}/мин. Доплата ${money(waitingFare())}.`);
    if(driver){if(r.status==='accepted')html+=actions(button('Я на месте','driver-arrived','primary'),button('Отказаться','driver-release','quiet'));if(r.status==='driver_waiting')html+=actions(button('Начать поездку','driver-start','primary'),button('Отказаться','driver-release','quiet'));if(r.status==='in_progress')html+=actions(button(r.waiting?'Завершить ожидание':'Начать ожидание','waiting-toggle'),button(r.stopIndex<state.booking.stops.length-1?`Остановка ${r.stopIndex+1} пройдена`:'Завершить поездку',r.stopIndex<state.booking.stops.length-1?'stop-complete':'completion','primary'))+demoControls(button('+ 1 мин ожидания','waiting-minute','quiet',r.waiting?'':'disabled'));html+=go(state.driver.next?'Следующий заказ принят':'Следующий заказ','next-order');}
    else html+=go('Детали поездки','order-detail')+(r.status!=='in_progress'?actions(button('Отменить поездку','cancel','quiet')):'')+demoControls(button('Следующее состояние','next-ride','quiet')+button(r.queued?'Обычная подача':'Водитель занят предыдущим заказом','queue-state','quiet'));
    return html;
  }
  function orderList(driver){const orders=[{id:'current',to:state.booking.stops.at(-1)||'Граховская школа',amount:total(),status:statusLabel()},...state.adminOrders.filter(o=>o.id!=='1048').map(o=>({id:o.id,to:o.name,amount:o.price,status:o.status})),...((driver?state.driverMore:state.historyMore)?[{id:'1038',to:'Азина, 12',amount:150,status:'Завершён'},{id:'1032',to:'Почта',amount:150,status:'Отменён'}]:[])];return orders.map(o=>go(`${o.to} · ${money(o.amount)}`,driver?'driver-trip':'order-detail',`${o.status} · ${o.id==='current'?'Сегодня':'8 сентября'}`,{id:o.id})).join('')}
  function rideDetails(driver){const historical=currentParams.id&&currentParams.id!=='current';const o=state.adminOrders.find(o=>o.id===currentParams.id);const amount=historical?(o?.price||150):total();return badge(historical?(o?.status||'Завершён'):statusLabel())+(historical?row('Откуда','Азина, 12')+row('Куда',o?.name||'Почта'):routeRows())+row('Тариф',historical?'Эконом':tariff==='child'?'Детский':'Эконом')+row('Зона расчёта','Грахово')+row('Оплата',paymentLabel())+row('Расстояние','1,8 км')+row('В пути','5 минут')+row('Стоимость маршрута',money(historical?amount:baseFare()))+(!historical?row('Повышение при поиске',money(state.booking.boost))+row('Ожидание',money(waitingFare())):'')+row('Итого',money(amount))+(driver?row('Комиссия сервиса',money(amount*state.rules.commission/100))+row('Остаётся водителю',money(amount*(1-state.rules.commission/100))):'')+row('Дата','9 сентября 2026, 09:38')+go('Переписка поездки','chat')+actions(button(driver?'Оценить пассажира':'Оценить водителя','rate-open','',driver?'data-driver="true"':''))}

