  register('admin-order','Детали заказа','admin',['admin/admin-order-detail-screen.tsx'],()=>{const o=state.adminOrders.find(o=>o.id===currentParams.id)||state.adminOrders[0];return badge(o.status)+row('Номер','#'+o.id)+row('Подача','Ачинцева, 5')+row('Назначение',o.name)+row('Тариф',o.price===220?'Детский':'Эконом')+row('Зона расчёта','Грахово')+row('Оплата',paymentLabel())+row('Расстояние / время','1,8 км · 5 минут')+row('Маршрут',money(o.price))+row('Повышение / ожидание',money(state.booking.boost)+' / '+money(waitingFare()))+row('Комиссия',money(o.price*state.rules.commission/100))+row('Итого',money(o.price))+go('Анна · пассажир','account','★ 4,9',{id:'p1'})+go('Сергей · водитель','account','Lada Vesta',{id:'d1'})+plateRow('Госномер',state.driver.plate)+`<h3>Чат пассажира и водителя</h3>`+badge('Только просмотр')+`<div style="margin-top:14px">${state.messages.map(m=>`<div class="flow-message ${m.mine?'mine':''}">${E(m.text)}</div>`).join('')}</div>`+row('Создан / обновлён','9 сентября 2026, 09:38 / 09:42')+actions(button('Обновить данные','refresh','quiet'))});
