  function accountList(kind){return lead(kind==='driver'?'Профили, доступ, комиссия и приоритеты по зонам.':'Профили, поездки, оценки и ограничения.')+`<label class="flow-field">Поиск по имени, телефону или госномеру<input id="flow-account-search" type="search" data-kind="${kind}"></label>`+tabs([['all','Все'],['available','Доступны'],['blocked','Заблокированы']],currentParams.filter||'all','account-filter')+`<div id="flow-account-results">${accountResults(kind,'')}</div>`}
