  function moderationForm(kind){return form('moderation',select('decision','Решение','approved',[['approved','Одобрить'],['rejected','Отклонить']])+area('reason','Комментарий модератора','','maxlength="500"'),'Применить решение',{kind})}
  function placeList(q){const items=state.places.filter(p=>(state.placeCategory==='Все'||p.category===state.placeCategory)&&[p.name,p.address,p.aliases].join(' ').toLowerCase().includes(q.toLowerCase()));return items.length?items.map(p=>`<div class="flow-order">${badge(p.active?'В поиске':'Скрыто',p.active?'':'warn')}${go(p.name,'place-edit',p.address,{id:p.id})}${actions(button(p.active?'Скрыть':'Вернуть в поиск','place-toggle',p.active?'quiet':'',`data-id="${p.id}"`),...(p.website?[button('Сайт','place-website','quiet',`data-id="${p.id}"`)]:[]))}</div>`).join(''):'<p class="flow-empty">Места не найдены</p>'}

